#!/usr/bin/env bash
# Generated by: GPT-6 (Codex)
# 安装脚本共用的 Bash 函数，不要从 .zshrc 加载。
set -euo pipefail
DOTFILES_ROOT=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)
DF_HOME=$(cd -- "${DOTFILES_TARGET_HOME:-$HOME}" && pwd -P)
DF_STATE="$DF_HOME/.local/state/dotfiles"
export DOTFILES_ROOT DOTFILES_TARGET_HOME="$DF_HOME"

die() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 1
}

# 备份清单用 Tab 分列、一行一条记录，因此拒绝含这些字符的路径。
for df_path in "$DOTFILES_ROOT" "$DF_HOME"; do
  if [[ $df_path == *$'\t'* || $df_path == *$'\n'* ]]; then
    die 'Tabs/newlines in paths are unsupported.'
  fi
done
unset df_path

require() {
  if ! command -v "$1" >/dev/null 2>&1; then
    die "Missing command: $1"
  fi
}

optional() {
  command -v "$1" >/dev/null 2>&1
}

check_dependencies() {
  local cmd
  local missing=0
  local commands=(
    bash git ln vim zsh tmux rg zoxide curl tar
    cp mv mkdir mktemp readlink realpath tac script
  )

  # 一次列出所有缺失项；不执行 sudo，也不自动安装系统软件。
  for cmd in "${commands[@]}"; do
    if ! optional "$cmd"; then
      printf 'Missing: %s\n' "$cmd" >&2
      missing=1
    fi
  done

  # Ubuntu 的 fd-find 包把命令命名为 fdfind。
  if ! optional fdfind && ! optional fd; then
    echo 'Missing: fdfind (or fd)' >&2
    missing=1
  fi
  if (( missing )); then
    echo 'Ubuntu: sudo apt install bash ca-certificates curl git zsh vim tmux fd-find ripgrep zoxide coreutils tar util-linux' >&2
    return 1
  fi
  printf 'Dependencies OK. Target: %s; repo: %s\n' "$DF_HOME" "$DOTFILES_ROOT"
}

begin_backup() {
  # mktemp 避免同一秒内重复安装复用备份目录；仅本人可读取备份。
  mkdir -p "$DF_STATE/backups"
  DF_BACKUP=$(mktemp -d "$DF_STATE/backups/$(date +%Y%m%d-%H%M%S)-XXXXXXXX")
  chmod 700 "$DF_BACKUP"
  printf '%s\n' "$DF_HOME" > "$DF_BACKUP/home"
  : > "$DF_BACKUP/links.tsv"
  export DF_BACKUP
}

module_context() {
  # 子模块必须使用外层创建的备份，不能绕开备份单独修改入口。
  if [[ -z ${DF_BACKUP:-} || ! -f $DF_BACKUP/links.tsv ]]; then
    die 'Run the repository install.sh --apply.'
  fi
  if [[ $(cat "$DF_BACKUP/home") != "$DF_HOME" ]]; then
    die 'Backup belongs to another home.'
  fi
}

link_path() {
  local source=$1
  local relative=$2
  local target parent id
  local had=0
  module_context
  if [[ ! -e $source ]]; then
    die "Missing link source: $source"
  fi
  if [[ $relative == /* || $relative == *..* ||
        $relative == *$'\t'* || $relative == *$'\n'* ]]; then
    die 'Invalid target path.'
  fi
  target="$DF_HOME/$relative"
  if [[ -L $target && $(readlink -f -- "$target") == $(realpath -- "$source") ]]; then
    printf 'Keep: %s\n' "$target"
    return
  fi
  # 父目录的符号链接可能把写操作带到 home 以外，先检查实际位置。
  parent=$(realpath -m -- "$(dirname -- "$target")")
  if [[ $parent != "$DF_HOME" && $parent != "$DF_HOME"/* ]]; then
    die "Target parent escapes home: $target"
  fi
  mkdir -p -- "$(dirname -- "$target")"
  id=$(wc -l < "$DF_BACKUP/links.tsv")
  if [[ -e $target || -L $target ]]; then
    had=1
  fi

  # 清单字段：编号、相对路径、新链接源、是否存在原文件。
  # 先记清单再移动文件，中断在“移动后、链接前”也可恢复。
  printf '%s\t%s\t%s\t%s\n' "$id" "$relative" "$source" "$had" >> "$DF_BACKUP/links.tsv"
  if (( had )); then
    mv -- "$target" "$DF_BACKUP/$id"
  fi
  ln -s -- "$source" "$target"
  touch "$DF_BACKUP/$id.linked"
  printf 'Link: %s -> %s\n' "$target" "$source"
}
link_file() {
  if [[ ! -f $1 ]]; then
    die "Not a file: $1"
  fi
  link_path "$@"
}

link_dir() {
  if [[ ! -d $1 ]]; then
    die "Not a directory: $1"
  fi
  link_path "$@"
}

clone_components() {
  local group=$1
  local kind name url revision
  local dest actual stage
  while IFS=$'\t' read -r kind name url revision; do
    if [[ $kind != "$group" ]]; then
      continue
    fi
    if [[ $group == zsh ]]; then
      dest="$DF_HOME/.zsh/$name"
    else
      dest="$DOTFILES_ROOT/config/vim/.vim/bundle/$name"
    fi

    # 已有仓库只检查，不自动 reset、pull 或覆盖本地修改。
    if [[ -e $dest || -L $dest ]]; then
      if [[ ! -d $dest/.git ]]; then
        die "Existing component is not a Git checkout: $dest"
      fi
      actual=$(git -C "$dest" rev-parse HEAD)
      if [[ $actual != "$revision" ]]; then
        die "Revision differs: $dest; reconcile deps/git-components.tsv manually."
      fi
      if [[ -n $(git -C "$dest" status --porcelain --untracked-files=no) ]]; then
        die "Modified component: $dest"
      fi
      printf 'Reuse: %s (%s)\n' "$name" "${actual:0:12}"
      continue
    fi
    mkdir -p -- "$(dirname -- "$dest")"
    stage=$(mktemp -d "${dest}.clone-XXXXXXXX")
    # 下载成功并切换到指定提交后才启用目录；失败的临时目录留作排查。
    git clone --no-checkout -- "$url" "$stage"
    git -C "$stage" checkout --detach "$revision"
    mv -- "$stage" "$dest"
  done < "$DOTFILES_ROOT/deps/git-components.tsv"
}
